import java.util.ArrayList;
import java.util.List;

// 1. Inheritance: Person base
abstract class Person {
    protected String name;
    public Person(String name) { this.name = name; }
    public String getName() { return name; }
}

class Professor extends Person { // IS-A Person
    public Professor(String name) { super(name); }
}

class Student extends Person { // IS-A Person
    public Student(String name) { super(name); }
}

// 2. Association: Student enrolls in Course
class Course {
    private String code;
    private Professor instructor; // Aggregation (Professor exists independently)

    public Course(String code, Professor instructor) {
        this.code = code;
        this.instructor = instructor;
    }
    public String getSummary() {
        return code + " taught by " + instructor.getName();
    }
}

// 3. Composition: Department owns its Office Rooms
class Department {
    static class OfficeRoom {
        private int roomNo;
        public OfficeRoom(int roomNo) { this.roomNo = roomNo; }
        public int getRoomNo() { return roomNo; }
    }

    private String deptName;
    private List<OfficeRoom> offices = new ArrayList<>(); // Composition
    private List<Professor> faculty = new ArrayList<>();   // Aggregation

    public Department(String deptName) {
        this.deptName = deptName;
        // Composing offices internally
        offices.add(new OfficeRoom(101));
        offices.add(new OfficeRoom(102));
    }

    public void addFaculty(Professor p) {
        faculty.add(p); // Aggregation: external professor
    }

    public void printReport() {
        System.out.println("Dept: " + deptName + " | Offices: " + offices.size() + " | Faculty: " + faculty.size());
    }
}

public class DomainSynthesisDemo {
    public static void main(String[] args) {
        Professor prof = new Professor("Dr. Shannon");
        Department cs = new Department("Computer Science");
        cs.addFaculty(prof);
        cs.printReport();

        Course infoTheory = new Course("CS-401", prof);
        System.out.println("Course: " + infoTheory.getSummary());
    }
}

