import java.util.ArrayList;
import java.util.List;

class MedicalBed {
    private int bedNumber;
    public MedicalBed(int num) { this.bedNumber = num; }
    public int getBedNumber() { return bedNumber; }
}

class HospitalWard {
    private String wardName;
    private List<MedicalBed> beds = new ArrayList<>(); // Composition: ward owns beds

    public HospitalWard(String wardName, int bedCapacity) {
        this.wardName = wardName;
        for (int i = 1; i <= bedCapacity; i++) {
            beds.add(new MedicalBed(i));
        }
    }
    public int getBedCount() { return beds.size(); }
    public String getWardName() { return wardName; }
}

class Nurse {
    private String name;
    public Nurse(String name) { this.name = name; }
    public String getName() { return name; }
}

class HospitalFacility {
    private String hospitalName;
    private List<HospitalWard> wards = new ArrayList<>(); // Composition
    private List<Nurse> nursingStaff = new ArrayList<>();  // Aggregation

    public HospitalFacility(String name) {
        this.hospitalName = name;
        wards.add(new HospitalWard("ICU", 4));
        wards.add(new HospitalWard("Pediatrics", 8));
    }

    public void employNurse(Nurse n) { nursingStaff.add(n); }

    public void printAudit() {
        System.out.println("Hospital: " + hospitalName);
        System.out.println("Wards operating: " + wards.size());
        System.out.println("Nurses employed: " + nursingStaff.size());
    }
}

public class HospitalSynthesisDemo {
    public static void main(String[] args) {
        HospitalFacility clinic = new HospitalFacility("Metro General");
        clinic.employNurse(new Nurse("Florence"));
        clinic.employNurse(new Nurse("Clara"));
        clinic.printAudit();
    }
}

