import java.util.ArrayList;
import java.util.List;

class Doctor {
    private String name;
    private String specialty;
    public Doctor(String name, String specialty) {
        this.name = name;
        this.specialty = specialty;
    }
    public String getBadge() { return name + " (" + specialty + ")"; }
}

class Bed {
    private int bedNumber;
    public Bed(int bedNumber) { this.bedNumber = bedNumber; }
    public int getBedNumber() { return bedNumber; }
}

class HospitalWard {
    private String wardName;
    private List<Bed> beds = new ArrayList<>(); // Composition
    private Doctor supervisingDoctor;           // Aggregation

    public HospitalWard(String wardName, int bedCount, Doctor doctor) {
        this.wardName = wardName;
        this.supervisingDoctor = doctor;
        for (int i = 1; i <= bedCount; i++) {
            beds.add(new Bed(i));
        }
    }

    public void printWardStatus() {
        System.out.println("Ward: " + wardName + " | Beds: " + beds.size() + " | Supervising: " + supervisingDoctor.getBadge());
    }
}

public class HospitalApp {
    public static void main(String[] args) {
        Doctor doc = new Doctor("Dr. Gregory House", "Diagnostics");
        HospitalWard ward = new HospitalWard("Ward-B", 6, doc);
        ward.printWardStatus();
    }
}

import java.util.ArrayList;
import java.util.List;

class Product {
    private String id;
    private String title;
    private double price;
    public Product(String id, String title, double price) {
        this.id = id;
        this.title = title;
        this.price = price;
    }
    public String getTitle() { return title; }
    public double getPrice() { return price; }
}

class CartItem {
    private Product product;
    private int quantity;
    public CartItem(Product product, int quantity) {
        this.product = product;
        this.quantity = quantity;
    }
    public double getSubtotal() {
        return product.getPrice() * quantity;
    }
    public String getLine() {
        return product.getTitle() + " x" + quantity + " = $" + getSubtotal();
    }
}

class ShoppingCart {
    private List<CartItem> items = new ArrayList<>();
    public void addItem(Product p, int qty) {
        items.add(new CartItem(p, qty));
    }
    public double getTotal() {
        double total = 0;
        for (CartItem item : items) total += item.getSubtotal();
        return total;
    }
    public void printSummary() {
        System.out.println("=== Shopping Cart ===");
        for (CartItem item : items) {
            System.out.println(" - " + item.getLine());
        }
        System.out.println("Total: $" + getTotal());
    }
}

public class ShopApp {
    public static void main(String[] args) {
        Product mouse = new Product("P1", "Wireless Mouse", 25.0);
        Product keyboard = new Product("P2", "Mechanical Keyboard", 80.0);

        ShoppingCart cart = new ShoppingCart();
        cart.addItem(mouse, 2);
        cart.addItem(keyboard, 1);
        cart.printSummary();
    }
}

