import java.util.ArrayList;
import java.util.List;

class Department {
    private String deptName;
    public Department(String deptName) { this.deptName = deptName; }
    public String getDeptName() { return deptName; }
}

class Company {
    private String name;
    private List<Department> departments = new ArrayList<>();

    public Company(String name) {
        this.name = name;
    }
    public void addDepartment(String deptName) {
        departments.add(new Department(deptName));
    }
    public void printStructure() {
        System.out.println("Company: " + name);
        for (Department d : departments) {
            System.out.println(" - Dept: " + d.getDeptName());
        }
    }
}

public class InvertedBugApp {
    public static void main(String[] args) {
        Company company = new Company("Acme Corp");
        company.addDepartment("Finance");
        company.addDepartment("R&D");
        company.printStructure();
    }
}

import java.util.ArrayList;
import java.util.List;

class Pilot {
    private String licenseNumber;
    private String name;
    public Pilot(String licenseNumber, String name) {
        this.licenseNumber = licenseNumber;
        this.name = name;
    }
    public String getProfile() {
        return "Capt. " + name + " [License: " + licenseNumber + "]";
    }
}

class Passenger {
    private String ticketNum;
    private String name;
    public Passenger(String ticketNum, String name) {
        this.ticketNum = ticketNum;
        this.name = name;
    }
    public String getTicket() {
        return "Tkt " + ticketNum + " (" + name + ")";
    }
}

class CommercialFlight {
    private String flightCode;
    private Pilot pilot; // Aggregation
    private List<Passenger> manifest = new ArrayList<>(); // Association

    public CommercialFlight(String flightCode, Pilot pilot) {
        this.flightCode = flightCode;
        this.pilot = pilot;
    }

    public void boardPassenger(Passenger p) {
        manifest.add(p);
    }

    public void dispatchFlight() {
        System.out.println("=== Flight " + flightCode + " Dispatch ===");
        System.out.println("Pilot in Command: " + pilot.getProfile());
        System.out.println("Passenger Manifest (" + manifest.size() + " boarded):");
        for (Passenger p : manifest) {
            System.out.println(" > " + p.getTicket());
        }
    }
}

public class AirlineApp {
    public static void main(String[] args) {
        Pilot pilot = new Pilot("P-8801", "Chesley Sullenberger");
        CommercialFlight flight = new CommercialFlight("FLIGHT-1549", pilot);
        flight.boardPassenger(new Passenger("T-01", "Alice"));
        flight.boardPassenger(new Passenger("T-02", "Bob"));
        flight.dispatchFlight();
    }
}
